insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'sla_5_v1'
from (values
('128.6.b.1.A',3,'A pertinent comment builds on what a speaker said. Which one does?','["Your example about the river helped me understand the setting.", "My dog is brown.", "Is it recess yet?", "I forgot my folder."]'::jsonb,0,'Pertinent comments connect to the speaker''s ideas.','original'),
('128.6.b.1.A',2,'Asking a speaker to explain what a term meant is a way to:','["end the talk", "clarify information", "show you stopped listening", "change the topic"]'::jsonb,1,'Relevant questions clarify meaning.','original'),
('128.6.b.1.B',3,'A teammate gives you four oral steps for a science lab. To restate them you should:','["repeat only step four", "skip the steps you forgot", "repeat each step in order using your own words", "say them backward"]'::jsonb,2,'Restating shows you understood the sequence.','original'),
('128.6.b.1.B',2,'Oral instructions with related steps often use words like:','["blue, green, red, pink", "up, down, left, there", "maybe, never, always, nobody", "first, then, after that, finally"]'::jsonb,3,'Sequence words keep instructions clear.','original'),
('128.6.b.1.C',3,'When expressing an opinion in a talk, you should back it up with:','["accurate information", "a louder voice", "longer pauses", "a guess"]'::jsonb,0,'Opinions are stronger with accurate support.','original'),
('128.6.b.1.C',3,'Which opinion is supported by accurate information?','["Everyone wants bike racks, I think.", "Our school needs more bike racks because forty students ride bikes daily.", "Our school needs more bike racks because I said so.", "Bike racks are cool, probably."]'::jsonb,1,'Facts make an opinion convincing.','original'),
('128.6.b.1.D',3,'A shared-responsibility plan for a group project lists:','["only the leader''s name", "the grade you expect", "who will do each task and when", "nothing in writing"]'::jsonb,2,'Plans divide tasks clearly.','original'),
('128.6.b.1.D',2,'Group members develop a plan of shared responsibilities so that:','["no one knows the job", "the project never ends", "one person does everything", "the work is divided fairly"]'::jsonb,3,'Shared plans support teamwork.','original'),
('128.6.b.10.A',3,'A speech urging students to join a recycling club has the purpose to:','["persuade", "confuse", "tease", "rhyme"]'::jsonb,0,'Calls to action persuade.','original'),
('128.6.b.10.A',3,'After reading a fable about a hare who bragged and lost a race, the author''s message is likely:','["Races are long.", "Bragging can lead to failure.", "Prizes are shiny.", "Hares are slow."]'::jsonb,1,'A message is the lesson in the text.','original'),
('128.6.b.10.B',3,'An author compares two cities side by side. This structure helps the purpose of:','["giving a date", "listing steps", "showing similarities and differences", "telling a joke"]'::jsonb,2,'Compare and contrast supports comparison.','original'),
('128.6.b.10.B',3,'Putting a text in cause-and-effect order helps the author:','["hide the main idea", "count the sentences", "avoid facts", "explain why events happened"]'::jsonb,3,'Cause and effect explains reasons.','original'),
('128.6.b.10.C',3,'Why might an author use a sidebar in a magazine article?','["to add extra information beside the main text", "to end the article", "to repeat the title", "to hide facts"]'::jsonb,0,'Sidebars give additional details.','original'),
('128.6.b.10.C',3,'An author puts a foreign word in italics to:','["show a mistake", "signal that the word is special", "shorten the line", "make it disappear"]'::jsonb,1,'Print features direct attention.','original'),
('128.6.b.10.D',3,'Which phrase is literal language?','["The pool swallowed me whole.", "The pool is an ocean.", "The pool is four feet deep.", "The pool is a giant bathtub."]'::jsonb,2,'Literal language means exactly what it says.','original'),
('128.6.b.10.E',3,'In first-person point of view, the reader learns:','["nothing at all", "everything about every character", "the author''s secrets", "only what the narrator knows and feels"]'::jsonb,3,'First-person narrators share their own view.','original'),
('128.6.b.10.E',3,'A narrator outside the story who describes what every character does uses:','["third-person point of view", "second-person point of view", "no point of view", "first-person point of view"]'::jsonb,0,'Third-person narrators stand outside the story.','original'),
('128.6.b.10.F',3,'Which sentence most helps readers hear a formal voice?','["Yo, we start at noon, okay?", "The committee will convene promptly at noon.", "Noon! Be there or be square!", "We kick off at noon, folks."]'::jsonb,1,'Formal word choice creates a formal voice.','original'),
('128.6.b.10.F',3,'An author''s voice is created by:','["the printer''s name", "paper color", "word choice, tone and sentence style", "page size"]'::jsonb,2,'Voice comes from how the author uses language.','original'),
('128.6.b.10.G',3,'An anecdote is a:','["list of facts", "table of data", "type of rhyme", "short story used to make a point"]'::jsonb,3,'Anecdotes illustrate ideas.','original'),
('128.6.b.10.G',3,'A speaker begins with a brief story about getting lost to show why maps matter. This is an:','["anecdote", "index", "glossary", "hyperbole"]'::jsonb,0,'A short personal story that supports a point is an anecdote.','original'),
('128.6.b.11.A',3,'Before drafting a letter to the principal, a writer should consider:','["the paper''s weight", "the purpose and the audience", "the pencil brand", "the weather"]'::jsonb,1,'Planning starts with purpose and audience.','original'),
('128.6.b.11.A',3,'Choosing a genre means deciding whether you will write:','["on Friday", "in blue ink", "a poem, a report or an opinion essay", "with big margins"]'::jsonb,2,'Genre is the type of text.','original'),
('128.6.b.11.B.i',3,'Transition words such as ''however'' and ''for example'' help writers:','["avoid punctuation", "skip paragraphs", "shorten words", "connect ideas smoothly"]'::jsonb,3,'Transitions link ideas.','original'),
('128.6.b.11.B.ii',3,'An engaging idea is developed with:','["relevant details and examples", "random facts", "extra spacing", "longer words only"]'::jsonb,0,'Relevant details support the idea.','original'),
('128.6.b.11.B.ii',3,'Which sentence adds a relevant detail to ''The festival was fun''?','["I own a bicycle.", "Colorful dancers twirled while a band played.", "Math is hard.", "It rained last July."]'::jsonb,1,'A relevant detail stays on the topic.','original'),
('128.6.b.11.C',3,'Deleting a sentence that does not support your main idea is part of:','["publishing", "brainstorming", "revising", "alphabetizing"]'::jsonb,2,'Revision includes adding, deleting and combining.','original'),
('128.6.b.11.C',3,'Combining ''The dog barked. The dog was loud.'' into one sentence improves:','["the title", "margins", "spelling only", "sentence structure"]'::jsonb,3,'Combining sentences smooths the writing.','original'),
('128.6.b.11.D.i',4,'Which choice fixes the comma splice ''We were tired, we kept walking''?','["We were tired, but we kept walking.", "We were tired, kept walking, we.", "We were tired we kept walking.", "We were tired, we kept walking."]'::jsonb,0,'Add a coordinating conjunction after the comma to join two complete thoughts.','original'),
('128.6.b.11.D.i',3,'Which verb completes ''The books on the shelf ___ old'' with subject-verb agreement?','["be", "are", "is", "am"]'::jsonb,1,'A plural subject, books, takes a plural verb.','original'),
('128.6.b.10.D',3,'A writer says the moon smiled down on the field. This figurative language is:','["a fact", "a rhyme", "personification", "literal language"]'::jsonb,2,'The moon is given a human action.','original'),
('128.6.b.11.B.i',3,'A strong introduction might begin with:','["the last sentence of the essay", "a list of page numbers", "a goodbye", "an interesting question or fact about the topic"]'::jsonb,3,'Introductions hook the reader and name the topic.','original'),
('128.6.b.11.D.vi',3,'A prepositional phrase can tell where something is, such as:','["sobre el escritorio", "es muy alto", "tengo hambre", "corre rápido"]'::jsonb,0,'Sobre el escritorio begins with a preposition and shows location.','original'),
('128.6.b.13.F',3,'Quotation marks and a citation are used when you:','["invent facts", "use an author''s exact words", "skip the source", "paraphrase loosely without credit"]'::jsonb,1,'Exact words need quotation marks and credit.','original'),
('128.6.b.2.B.i',3,'Which spelling of the place where trains stop is correct?','["estacion", "estácion", "estación", "estaciòn"]'::jsonb,2,'Estación is stressed on the last syllable and ends in n.','original'),
('128.6.b.6.H',3,'Merging details from a map and a passage to understand a trip is:','["skipping", "alphabetizing", "scanning", "synthesizing"]'::jsonb,3,'Synthesis combines sources into new understanding.','original'),
('128.6.b.9.F',3,'Which feature is common in a digital text?','["hyperlinks that open related pages", "page numbers only", "a paper cover", "ink smudges"]'::jsonb,0,'Digital texts often include links.','original'),
('128.6.b.11.D.ii',4,'Which verb phrase uses a past participle?','["terminaré", "había terminado", "terminando", "termino"]'::jsonb,1,'Haber plus a participle forms a perfect tense.','original'),
('128.6.b.11.D.ii',3,'''Mañana comeremos temprano'' is in the:','["imperfect past", "present tense", "future tense", "simple past"]'::jsonb,2,'Mañana and the -emos future ending show the future.','original'),
('128.6.b.11.D.iii',3,'Which phrase has the correct gender-specific article?','["el mano", "los mano", "un mano", "la mano"]'::jsonb,3,'Mano is feminine even though it ends in o.','original'),
('128.6.b.11.D.iii',3,'Which is the plural of ''canción''?','["canciones", "canciónes", "cancións", "cancionos"]'::jsonb,0,'Nouns ending in -ción form the plural with -ciones.','original'),
('128.6.b.11.D.iv',3,'In ''Esta tarea es menos difícil que la otra'', the phrase menos difícil is a:','["verb", "comparative", "noun", "superlative"]'::jsonb,1,'Menos plus que compares two things.','original'),
('128.6.b.11.D.iv',3,'Which phrase is a superlative?','["rápida", "tan rápida como Ana", "la más rápida del equipo", "más rápida que Ana"]'::jsonb,2,'A superlative names the highest degree in a group.','original'),
('128.6.b.11.D.ix',3,'In Spanish, titles of books usually capitalize:','["only the last word", "no words", "every word", "only the first word and proper nouns"]'::jsonb,3,'Spanish title capitalization is limited.','original'),
('128.6.b.11.D.ix',3,'Which is the name of a historical document that should be capitalized?','["the Declaration of Independence", "the lunch menu", "the class schedule", "the weather report"]'::jsonb,0,'Names of historical documents are capitalized.','original'),
('128.6.b.11.D.v',3,'Which adverb tells how often?','["muy", "siempre", "aquí", "despacio"]'::jsonb,1,'Siempre means always.','original'),
('128.6.b.11.D.v',3,'Which adverb tells degree (how much)?','["atrás", "hoy", "muy", "nunca"]'::jsonb,2,'Muy means very.','original'),
('128.6.b.11.D.vi',3,'Hacia, desde and entre are all:','["verbs", "conjunctions", "adjectives", "prepositions"]'::jsonb,3,'These words introduce prepositional phrases.','original'),
('128.6.b.11.D.vii',3,'Pronouns that follow prepositions, such as mí, ti and él, are called:','["prepositional pronouns", "possessive adjectives", "interjections", "reflexive pronouns"]'::jsonb,0,'They come after a preposition.','original'),
('128.6.b.11.D.vii',3,'Which sentence uses a reflexive pronoun?','["Ellos comen.", "Ella se peina.", "Ella peina a su hermana.", "Ella canta bien."]'::jsonb,1,'Se shows the subject does the action to itself.','original'),
('128.6.b.11.D.viii',3,'A compound predicate has two verbs for one subject. Which fits?','["Tomás lee.", "Lee Tomás.", "Tomás lee y escribe.", "Tomás y Ana leen."]'::jsonb,2,'Lee and escribe share the subject Tomás.','original'),
('128.6.b.11.D.viii',3,'The conjunction ''o'' in ''té o café'' joins:','["two verbs only", "two sentences only", "two titles", "two choices"]'::jsonb,3,'O joins alternatives.','original'),
('128.6.b.11.D.x',4,'In compound sentences, a comma usually comes before:','["a coordinating conjunction joining two complete thoughts", "every noun", "the last period", "every verb"]'::jsonb,0,'Use a comma before the conjunction in a compound sentence.','original'),
('128.6.b.11.D.x',3,'An em dash in written dialogue is used to:','["join two numbers", "show that a character is speaking", "mark a title", "end a paragraph"]'::jsonb,1,'Spanish dialogue often begins with an em dash.','original'),
('128.6.b.11.D.xi',3,'Which spelling names the place where you borrow books?','["bibloteca", "biblioteka", "biblioteca", "viblioteca"]'::jsonb,2,'Biblioteca uses b and c.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Spanish Language Arts and English as a Second Language' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'sla_5_v1'
from (values
('128.6.b.11.D.xi',3,'Which spelling names water falling from clouds?','["lluvía", "yuvia", "lluvya", "lluvia"]'::jsonb,3,'Lluvia starts with ll.','original'),
('128.6.b.11.E',2,'To publish a report for the school community you might:','["post a final copy in the library", "skip editing", "erase the report", "keep the first draft in your desk"]'::jsonb,0,'Publishing shares final work.','original'),
('128.6.b.11.E',3,'Before publishing, a writer should:','["hide the audience", "edit for spelling and punctuation", "tear up the draft", "remove the title"]'::jsonb,1,'Final copies are edited.','original'),
('128.6.b.12.A',3,'A personal narrative uses:','["a table of data", "third-person facts only", "first-person point of view and real events", "a list of steps"]'::jsonb,2,'Personal narratives tell about your own experience.','original'),
('128.6.b.12.A',3,'A poem might use:','["citations and a bibliography", "legal terms", "tables, bullets and sidebars", "images, rhythm and figurative language"]'::jsonb,3,'Poems rely on sound and imagery.','original'),
('128.6.b.12.B',3,'A brief composition that conveys information about a topic begins with:','["a topic sentence", "a rhyme", "a joke", "a recipe"]'::jsonb,0,'A topic sentence names the subject.','original'),
('128.6.b.12.B',3,'Which sentence belongs in an informational composition about volcanoes?','["Volcanoes are boring.", "Magma rises through cracks in Earth''s crust.", "Once upon a time there was a dragon.", "I want a pet lizard."]'::jsonb,1,'Informational writing presents facts.','original'),
('128.6.b.12.C',3,'An opinion essay states a claim and gives:','["rhymes and riddles", "jokes and songs", "reasons and evidence", "directions and steps"]'::jsonb,2,'Argumentative writing supports claims.','original'),
('128.6.b.12.C',3,'Which is the strongest evidence for ''School lunches should include more fruit''?','["I like lunch.", "Fruit is my favorite.", "Fruit is colorful.", "A study found students who ate fruit paid better attention."]'::jsonb,3,'Evidence from a study is convincing.','original'),
('128.6.b.12.D',3,'A letter that requests information should include:','["a clear question and a polite closing", "a long story", "a joke only", "no greeting"]'::jsonb,0,'Correspondence has a clear purpose.','original'),
('128.6.b.12.D',3,'Which opening fits a letter requesting information from a museum?','["Hey, what''s up?", "I am writing to ask about your summer tour times.", "Give me tickets.", "I don''t like museums."]'::jsonb,1,'A request letter states its purpose politely.','original'),
('128.6.b.13.A',3,'To clarify a research question, a student can:','["answer it with a guess", "make it vaguer", "make it more specific", "delete it"]'::jsonb,2,'Clear questions guide research.','original'),
('128.6.b.13.A',3,'Which question is narrow enough for a short report?','["What is science?", "What is everything about animals?", "Why is life?", "How do monarch butterflies migrate?"]'::jsonb,3,'A focused question is researchable.','original'),
('128.6.b.13.B',3,'Developing a research plan with an adult means you:','["list steps, sources and deadlines", "wait until the last day", "choose your favorite color", "avoid asking for help"]'::jsonb,0,'Plans organize the work.','original'),
('128.6.b.13.B',3,'A deadline in a research plan tells you:','["which font to use", "when each step should be done", "how long a source is", "who the author is"]'::jsonb,1,'Deadlines schedule tasks.','original'),
('128.6.b.13.C',3,'Which source is likely best for facts about volcanoes?','["a comic strip", "a cookbook", "a science encyclopedia", "a joke book"]'::jsonb,2,'Relevant, reliable sources match the topic.','original'),
('128.6.b.13.C',3,'A reliable website for research often ends with:','[".boo", ".lol", ".wow", ".gov or .edu"]'::jsonb,3,'Government and education sites tend to be reliable.','original'),
('128.6.b.13.D',3,'An interview with a person who lived through a hurricane is a:','["primary source", "dictionary", "secondary source", "index"]'::jsonb,0,'First-hand accounts are primary.','original'),
('128.6.b.13.D',3,'An encyclopedia article about a hurricane is a:','["primary source", "secondary source", "first-hand account", "eyewitness"]'::jsonb,1,'Secondary sources summarize other information.','original'),
('128.6.b.13.E',3,'Which note shows understanding of a source about owls?','["See page four.", "Owls.", "Owls hunt at night using sharp hearing.", "Interesting."]'::jsonb,2,'A meaningful note restates an idea.','original'),
('128.6.b.13.E',3,'Summarizing a source shows you can:','["hide the topic", "list page numbers", "copy every sentence", "state the main points briefly"]'::jsonb,3,'A summary is short and complete.','original'),
('128.6.b.13.F',3,'A good paraphrase keeps the meaning but changes:','["the wording and sentence structure", "the facts", "the topic", "the source''s meaning"]'::jsonb,0,'Paraphrase uses your own words.','original'),
('128.6.b.13.G',3,'A bibliography is a list of:','["jokes", "sources used in research", "pages you skipped", "words you misspelled"]'::jsonb,1,'It credits sources.','original'),
