('128.6.b.7.A',2,'Personal connections can come from:','["only assigned tests", "no texts", "self-selected texts you choose to read", "blank pages"]'::jsonb,2,'Self-selected texts invite connections.','original'),
('128.6.b.7.B',3,'A response that compares two texts should tell:','["which has a better cover", "which has more pages", "which is heavier", "how they are alike and different"]'::jsonb,3,'Comparing and contrasting examines similarities and differences.','original'),
